from fastapi import FastAPI, Depends, Response
from typing import Annotated
from starlette.responses import Response as StarletteResponse
from fastapi.testclient import TestClient

def modify_response():
    return Response(content="modified")

app = FastAPI()

@app.get("/annotated")
def endpoint_annotated(response: Annotated[Response, Depends(modify_response)]):
    return response

@app.get("/default")
def endpoint_default(response: Response = Depends(modify_response)):
    return response

@app.get("/regular")
def endpoint_regular(response: Response):
    return response

if __name__ == "__main__":
    client = TestClient(app)

    res_annotated = client.get("/annotated")
    print(f"Annotated: {res_annotated.status_code}, {res_annotated.text}")
    assert res_annotated.status_code == 200
    assert res_annotated.text == "modified"

    res_default = client.get("/default")
    print(f"Default: {res_default.status_code}, {res_default.text}")
    assert res_default.status_code == 200
    assert res_default.text == "modified"

    res_regular = client.get("/regular")
    print(f"Regular: {res_regular.status_code}")
    assert res_regular.status_code == 200

    print("All tests passed!")

